{"command":"cat <<'EOF' > /tmp/test_rust/src/test_dur.rs
use std::time::Duration;

pub fn parse_duration(s: &str) -> Result<Duration, String> {
    let s = s.trim();
    if s.is_empty() {
        return Err("expected number at 0".to_string());
    }

    let mut total_nanos: u128 = 0;
    let mut idx = 0;
    let bytes = s.as_bytes();

    while idx < bytes.len() {
        while idx < bytes.len() && bytes[idx].is_ascii_whitespace() {
            idx += 1;
        }
        if idx >= bytes.len() {
            break;
        }

        let num_start = idx;
        let mut has_dot = false;
        while idx < bytes.len() && (bytes[idx].is_ascii_digit() || bytes[idx] == b'.') {
            if bytes[idx] == b'.' {
                if has_dot {
                    break;
                }
                has_dot = true;
            }
            idx += 1;
        }

        if num_start == idx {
            return Err(format!("expected number at {}", idx));
        }

        let num_str = &s[num_start..idx];
        let val: f64 = num_str.parse().map_err(|_| format!("expected number at {}", num_start))?;

        while idx < bytes.len() && bytes[idx].is_ascii_whitespace() {
            idx += 1;
        }

        let unit_start = idx;
        while idx < bytes.len() && bytes[idx].is_ascii_alphabetic() {
            idx += 1;
        }

        let unit_str = &s[unit_start..idx];
        let multiplier_nanos: u128 = match unit_str {
            "ns" | "nanos" | "nanosecond" | "nanoseconds" => 1,
            "us" | "micros" | "microsecond" | "microseconds" => 1_000,
            "ms" | "millis" | "millisecond" | "milliseconds" => 1_000_000,
            "s" | "sec" | "secs" | "second" | "seconds" => 1_000_000_000,
            "m" | "min" | "mins" | "minute" | "minutes" => 60 * 1_000_000_000,
            "h" | "hr" | "hrs" | "hour" | "hours" => 3600 * 1_000_000_000,
            "d" | "day" | "days" => 86400 * 1_000_000_000,
            "w" | "week" | "weeks" => 7 * 86400 * 1_000_000_000,
            "y" | "year" | "years" => 365 * 86400 * 1_000_000_000,
            "" => {
                return Err(format!("expected time unit at {}", unit_start));
            }
            _ => return Err(format!("unknown time unit '{}' at {}", unit_str, unit_start)),
        };

        total_nanos += (val * multiplier_nanos as f64) as u128;
    }

    Ok(Duration::from_nanos(total_nanos as u64))
}

fn main() {
    println!("{:?}", parse_duration("2h10min"));
    println!("{:?}", parse_duration("5s"));
    println!("{:?}", parse_duration("abc"));
    println!("{:?}", parse_duration("10x"));
}
EOF
