                return Err(format!("expected time unit at {}", unit_start));
            }
            _ => return Err(format!("unknown time unit '{}' at {}", unit_str, unit_start)),
        };

        total_nanos += (val * multiplier_nanos as f64) as u128;
    }

    Ok(Duration::from_nanos(total_nanos as u64))
}

pub fn random_ip_v4() -> String {
    let mut rng = rand::thread_rng();
    format!(
        "{}.{}.{}.{}",
        rng.gen_range(1..255),
        rng.gen_range(0..255),
        rng.gen_range(0..255),
        rng.gen_range(1..255)
    )
}

pub fn random_ip_v6() -> String {
    let mut rng = rand::thread_rng();
    format!(
        "{:x}:{}:{:x}:{:x}:{:x}:{:x}:{:x}:{:x}",
        rng.gen_range(1..0xffff),
        rng.gen_range(0..0xffff),
        rng.gen_range(0..0xffff),
        rng.gen_range(0..0xffff),
        rng.gen_range(0..0xffff),
        rng.gen_range(0..0xffff),
        rng.gen_range(0..0xffff),
        rng.gen_range(1..0xffff)
    )
}

pub fn random_ip() -> String {
    let mut rng = rand::thread_rng();
    if rng.gen_bool(0.7) {
        random_ip_v4()
    } else {
        random_ip_v6()
    }
}

pub fn random_hex(len: usize) -> String {
    let mut rng = rand::thread_rng();
    let chars: &[u8] = b"0123456789abcdef";
    (0..len)
        .map(|_| {
            let idx = rng.gen_range(0..chars.len());
            chars[idx] as char
        })
        .collect()
}
