use rand::Rng;
use std::sync::atomic::{AtomicBool, Ordering};
use std::time::{Duration, Instant};

pub static RUNNING: AtomicBool = AtomicBool::new(true);

pub struct Context {
    pub speed_factor: f64,
    pub instant_print_lines: usize,
    pub start_time: Instant,
    pub exit_after_time: Option<Duration>,
}

impl Context {
    pub fn new(
        speed_factor: f64,
        instant_print_lines: usize,
        start_time: Instant,
        exit_after_time: Option<Duration>,
    ) -> Self {
        Self {
            speed_factor,
            instant_print_lines,
            start_time,
            exit_after_time,
        }
    }

    pub fn should_exit(&self) -> bool {
        if !RUNNING.load(Ordering::SeqCst) {
            return true;
        }
        if let Some(limit) = self.exit_after_time {
            if self.start_time.elapsed() >= limit {
                return true;
            }
        }
        false
    }

    pub fn sleep(&mut self, millis: u64) {
        if self.should_exit() {
            return;
        }
        if self.instant_print_lines > 0 {
            self.instant_print_lines -= 1;
            return;
        }
        let delay_secs = (millis as f64 / 1000.0) / self.speed_factor;
        let sleep_dur = Duration::from_secs_f64(delay_secs);
        let check_interval = Duration::from_millis(15);
        let mut elapsed = Duration::ZERO;
        while elapsed < sleep_dur {
            if self.should_exit() {
                break;
            }
            let step = check_interval.min(sleep_dur - elapsed);
            std::thread::sleep(step);
            elapsed += step;
        }
    }
}

