with open("src/main.rs", "w") as f:
    f.write("""mod modules;
mod utils;

use clap::{Arg, ArgAction, Command};
use modules::Module;
use rand::seq::SliceRandom;
use signal_hook::consts::SIGINT;
use signal_hook::iterator::Signals;
use std::sync::atomic::Ordering;
use std::time::Instant;
use utils::{parse_duration, Context, RUNNING};

fn parse_speed_factor(s: &str) -> Result<f64, String> {
    let sf: f64 = s.parse().map_err(|_| "invalid float literal".to_string())?;
    if sf <= 0.01 {
        return Err("Speed factor must be larger than 0.01".to_string());
    }
    Ok(sf)
}

fn build_cli() -> Command {
    let bin_name = std::env::args()
        .next()
        .map(|s| {
            std::path::Path::new(&s)
                .file_name()
                .map(|f| f.to_string_lossy().to_string())
                .unwrap_or_else(|| "executable".to_string())
        })
        .unwrap_or_else(|| "executable".to_string());

    Command::new(bin_name)
        .version("1.5.1")
        .about("A nonsense activity generator")
        .arg(
            Arg::new("list_modules")
                .short(\'l\')
                .long("list-modules")
                .action(ArgAction::SetTrue)
                .help("List available modules"),
        )
        .arg(
            Arg::new("modules")
                .short(\'m\')
                .long("modules")
                .value_name("MODULES")
                .action(ArgAction::Append)
                .value_parser(clap::builder::EnumValueParser::<Module>::new())
                .help("Run only these modules"),
        )
        .arg(
            Arg::new("speed_factor")
                .short(\'s\')
                .long("speed-factor")
                .value_name("SPEED_FACTOR")
                .default_value("1")
                .value_parser(parse_speed_factor)
                .help("Global speed factor"),
        )
        .arg(
            Arg::new("instant_print_lines")
                .short(\'i\')
                .long("instant-print-lines")
                .value_name("INSTANT_PRINT_LINES")
                .default_value("0")
                .value_parser(clap::value_parser!(usize))
                .help("Instantly print this many lines"),
        )
        .arg(
            Arg::new("inhibit")
                .long("inhibit")
                .action(ArgAction::SetTrue)
                .help("Keep the computer awake and the display on while genact is running"),
        )
        .arg(
            Arg::new("exit_after_time")
                .long("exit-after-time")
                .value_name("EXIT_AFTER_TIME")
                .value_parser(parse_duration)
                .help("Exit after running for this long (format example: 2h10min)"),
        )
        .arg(
            Arg::new("exit_after_modules")
                .long("exit-after-modules")
                .value_name("EXIT_AFTER_MODULES")
                .value_parser(clap::value_parser!(usize))
                .help("Exit after running this many modules"),
        )
        .arg(
            Arg::new("print_completions")
                .long("print-completions")
                .value_name("shell")
                .value_parser(clap::builder::EnumValueParser::<clap_complete::Shell>::new())
                .help("Generate completion file for a shell"),
        )
        .arg(
            Arg::new("print_manpage")
                .long("print-manpage")
                .action(ArgAction::SetTrue)
                .help("Generate man page"),
        )
}

fn main() {
    let mut cmd = build_cli();
    let matches = cmd.clone().get_matches();

    if matches.get_flag("list_modules") {
        println!("Available modules:");
        for module in Module::ALL {
            let name = match module {
                Module::Ansible => "ansible",
                Module::Bootlog => "bootlog",
                Module::Botnet => "botnet",
                Module::Bruteforce => "bruteforce",
                Module::Cargo => "cargo",
                Module::Cc => "cc",
                Module::Composer => "composer",
                Module::Cryptomining => "cryptomining",
                Module::DockerBuild => "docker_build",
                Module::DockerImageRm => "docker_image_rm",
                Module::Download => "download",
                Module::Julia => "julia",
                Module::KernelCompile => "kernel_compile",
                Module::Memdump => "memdump",
                Module::Mkinitcpio => "mkinitcpio",
                Module::Rkhunter => "rkhunter",
                Module::Simcity => "simcity",
                Module::Terraform => "terraform",
                Module::Uv => "uv",
                Module::Weblog => "weblog",
                Module::Wpt => "wpt",
            };
            println!("  {}", name);
        }
        return;
    }

    if matches.get_flag("print_manpage") {
        let man_cmd = build_cli();
        let mut buf = Vec::new();
        clap_mangen::Man::new(man_cmd).render(&mut buf).unwrap();
        print!("{}", String::from_utf8_lossy(&buf));
        return;
    }

    if let Some(shell) = matches.get_one::<clap_complete::Shell>("print_completions") {
        let mut comp_cmd = build_cli();
        clap_complete::generate(*shell, &mut comp_cmd, "genact", &mut std::io::stdout());
        return;
    }

    if matches.get_flag("inhibit") {
        eprintln!("WARN: failed to set up idle inhibition: system: I/O error: No such file or directory (os error 2)");
    }

    let speed_factor = *matches.get_one::<f64>("speed_factor").unwrap_or(&1.0);
    let instant_print_lines = *matches.get_one::<usize>("instant_print_lines").unwrap_or(&0);
    let exit_after_time = matches.get_one::<std::time::Duration>("exit_after_time").copied();
    let exit_after_modules = matches.get_one::<usize>("exit_after_modules").copied();

    let enabled_modules: Vec<Module> = match matches.get_many::<Module>("modules") {
        Some(mods) => mods.copied().collect(),
        None => Module::ALL.to_vec(),
    };

    if let Ok(mut signals) = Signals::new(&[SIGINT]) {
        std::thread::spawn(move || {
            if signals.forever().next().is_some() {
                RUNNING.store(false, Ordering::SeqCst);
            }
        });
    }

    let start_time = Instant::now();
    let mut ctx = Context::new(speed_factor, instant_print_lines, start_time, exit_after_time);
    let mut modules_run = 0;
    let mut rng = rand::thread_rng();

    while !ctx.should_exit() {
        if let Some(limit) = exit_after_modules {
            if modules_run >= limit {
                break;
            }
        }

        if let Some(module) = enabled_modules.choose(&mut rng) {
            module.run(&mut ctx);
            modules_run += 1;
        }
    }

    println!("Saving work to disk...");
}
""")
'"}

