with open("src/modules/bruteforce.rs", "w") as f:
    f.write("""use crate::utils::{random_hex, Context};
use rand::seq::SliceRandom;
use rand::Rng;

const WORDLIST: &[&str] = &[
    "lucienne55", "hosea80", "alexane26", "ashlynn86", "louie04", "admin123", "password", "secret", "welcome1", "pass1234"
];

pub fn run(ctx: &mut Context) {
    let mut rng = rand::thread_rng();
    let hashes: Vec<String> = (0..5).map(|_| random_hex(64)).collect();
    let passwords: Vec<String> = (0..5).map(|_| WORDLIST.choose(&mut rng).unwrap().to_string()).collect();

    println!("=> Hashes to decrypt");
    for h in &hashes {
        println!("  {}", h);
    }
    println!();

    let spinners = ['|', '/', '-', '\\\\'];
    let colors = [203, 209, 208, 178, 184, 148, 154, 119, 83, 84, 48, 43, 44, 38, 33, 69, 63, 99, 129, 128, 164, 163, 198, 204];

    for i in 0..30 {
        if ctx.should_exit() {
            return;
        }
        let spin = spinners[i % spinners.len()];
        let mut bar = String::new();
        for col in 0..30 {
            let color = colors[(i + col) % colors.len()];
            let char = if col == i % 30 { spin } else if col < i % 30 { \'=\' } else { \' \' };
            bar.push_str(&format!("\\x1b[38;5;{}m{}\\x1b[0m", color, char));
        }
        print!("\\r\\x1b[2K=> Extracting Rainbow Table [{}]", bar);
        use std::io::Write;
        let _ = std::io::stdout().flush();
        ctx.sleep(50);
    }
    println!("\\n");

    for _ in 0..50 {
        if ctx.should_exit() {
            return;
        }
        let hash = hashes.choose(&mut rng).unwrap();
        let candidate = WORDLIST.choose(&mut rng).unwrap();
        println!(" :: \\x1b[32m{}\\x1b[0m\\x1b[31m{}\\x1b[0m :: ", hash, candidate);
        ctx.sleep(20);
    }

    println!("=> Match found");
    for (h, p) in hashes.iter().zip(passwords.iter()) {
        println!("  {}:\\x1b[1m{}\\x1b[0m", h, p);
    }
}
""")

