with open("src/modules/download.rs", "w") as f:
    f.write("""use crate::utils::{terminal_width, Context};
use rand::Rng;

pub fn run(ctx: &mut Context) {
    let _ = terminal_width(); // ensures terminal width is checked
    let mut rng = rand::thread_rng();

    let filename = "kernel-5.15.0-generic.tar.xz";
    let total_mb = 120.0;

    for percent in 0..=100 {
        if ctx.should_exit() {
            return;
        }
        let downloaded = (percent as f64 / 100.0) * total_mb;
        let speed: f64 = rng.gen_range(50.0..90.0);
        let eta = ((total_mb - downloaded) / speed) as usize;

        let bar_len = 20;
        let filled = (percent * bar_len) / 100;
        let mut bar = String::new();
        for i in 0..bar_len {
            if i < filled {
                bar.push(\'=\');
            } else if i == filled {
                bar.push(\'█\');
            } else {
                bar.push(\' \');
            }
        }

        print!(
            "\\x1b[2K\\x1b[0G{:20} {:3}%[{}] {:.2}MiB    {:.2}MiB/s   eta {}s",
            filename, percent, bar, downloaded, speed, eta
        );
        use std::io::Write;
        let _ = std::io::stdout().flush();
        ctx.sleep(40);
    }
    println!();
}
""")

