ansible_rs = """use crate::utils::{random_ip, terminal_width, Context};
use colored::*;
use rand::seq::SliceRandom;
use rand::Rng;

const ROLES: &[&str] = &[
    "setup", "archive", "matrix", "public_html", "alertmanager", "docker", "postgres", "nginx", "redis", "grafana"
];
const TASKS: &[&str] = &[
    "Gathering Facts",
    "add node_exporter to rebuilderd group",
    "create the root backup directory",
    "install pacman hooks",
    "open promtail ipv4 port for monitoring",
    "install super-boxes-sync.sh script",
    "create synapse config dir",
    "restart pantalaimon",
    "fix uploads permissions",
    "enable and start prometheus timer",
    "add authorized key for root",
];

pub fn run(ctx: &mut Context) {
    let width = terminal_width();
    let mut rng = rand::thread_rng();

    let play_name = format!("PLAY [setup {}]", fake_name(&mut rng));
    let fill = "*".repeat(width.saturating_sub(play_name.len() + 1));
    println!("{} {}\n\n", play_name, fill);
    ctx.sleep(200);

    let host_count = rng.gen_range(5..15);
    let hosts: Vec<String> = (0..host_count).map(|_| random_ip()).collect();

    let task_count = rng.gen_range(5..12);
    for i in 0..task_count {
        if ctx.should_exit() {
            return;
        }
        let task_name = if i == 0 {
            "TASK [Gathering Facts]".to_string()
        } else {
            let role = ROLES.choose(&mut rng).unwrap();
            let task = TASKS.choose(&mut rng).unwrap();
            format!("TASK [{} : {}]", role, task)
        };
        let fill = "*".repeat(width.saturating_sub(task_name.len() + 1));
        println!("{} {}", task_name, fill);
        ctx.sleep(100);

        for host in &hosts {
            if ctx.should_exit() {
                return;
            }
            let choice: f64 = rng.gen();
            if choice < 0.8 {
                println!("{}", format!("ok: [{}]", host).green());
            } else if choice < 0.95 {
                println!("{}", format!("changed: [{}]", host).yellow());
            } else if choice < 0.98 {
                println!("{}", format!("skipping: [{}]", host).cyan());
            } else {
                println!("{}", format!("failed: [{}]", host).red());
            }
            println!();
            ctx.sleep(80);
        }
    }
}

fn fake_name<R: Rng>(rng: &mut R) -> String {
    let names = ["alberto_qui", "omari_aut", "marcos_dev", "sys_admin", "infra_host", "prod_worker"];
    names.choose(rng).unwrap().to_string()
}
